from pathlib import Path
p=Path('src/Notes.jsx');s=p.read_text(encoding='utf-8-sig');s=s.replace("data.consent=true;try{", """data.consent=true;try{if(path==='notes'){
 data.links=(data.links||'').split('\\n').map(v=>v.trim()).filter(Boolean);data.uploads=[];
 for(const file of form.elements.files.files){
 if(file.size>10*1024*1024)throw Error('Each file must be 10 MB or smaller.');
 const r=await fetch(`${API}/public/notes/upload`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const asset=await r.json();if(!r.ok)throw Error(asset.error||'Upload failed.');data.uploads.push({...asset,name:file.name});
 }delete data.files;
 }""")
s=s.replace('<div className="notes-body">{selected.body}</div>','<div className="notes-body">{selected.body}</div><Attachments items={selected.attachments}/>' )
s=s.replace('<strong>{p.category}</strong>','<strong>{p.attachments?.some(a=>a.type===\'pdf\')?\'PDF NOTES\':p.category}</strong>')
s=s.replace('<h2>{p.title}</h2>','<h2>{p.title}</h2>{p.topic&&<span className="notes-kicker">{p.topic}</span>}')
s=s.replace('<label className="notes-consent"><input type="checkbox" required/> I wrote', '<label>PDFs or images (up to 3, 10 MB each)<input type="file" name="files" multiple accept=".pdf,.png,.jpg,.jpeg,.webp"/></label><label>Reference links (HTTPS, one per line)<textarea name="links" rows={2}/></label><label className="notes-consent"><input type="checkbox" required/> I wrote')
s += "\nfunction Attachments({items=[]}){return <div className=\"note-attachments\">{items.map((a,i)=><a key={i} href={a.url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"note-resource\">{a.type==='image'?<img src={a.url} alt={a.name} loading=\"lazy\"/>:<span className=\"resource-symbol\">{a.type==='pdf'?'PDF':'↗'}</span>}<strong>{a.name}</strong><small>Open {a.type} ↗</small></a>)}</div>}\n"
p.write_text(s,encoding='utf-8')
p=Path('admin/src/NotesAdmin.jsx');s=p.read_text(encoding='utf-8-sig').replace("notify:false};","notify:false,attachments:[],topic:''};");s=s.replace("id:p._id,notify:false","id:p._id,notify:false,attachments:p.attachments||[],topic:p.topic||''");s=s.replace("['title','author','summary','body']","['title','author','topic','summary','body']");s=s.replace('<label>Topic <select','<label>Attachments (JSON: name, url, type)<textarea rows={6} defaultValue={JSON.stringify(draft.attachments,null,2)} key={draft.id||\'new\'} onBlur={e=>{try{setDraft({...draft,attachments:JSON.parse(e.target.value)})}catch{setMessage(\'Invalid attachment JSON\')}}}/></label><label>Upload PDF or image<input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={async e=>{const file=e.target.files[0];if(!file)return;setBusy(true);try{const result=await request(\'/admin/media\',{csrf,method:\'POST\',headers:{\'Content-Type\':\'application/octet-stream\'},body:file});const a=result.asset||result;setDraft({...draft,attachments:[...(draft.attachments||[]),{url:a.url,name:file.name,type:file.type===\'application/pdf\'?\'pdf\':\'image\'}]});setMessage(\'Uploaded. Save the note to attach it.\')}catch(e){setMessage(e.message)}finally{setBusy(false)}}}/></label><label>Topic <select');p.write_text(s,encoding='utf-8')
